// Source:        NDR / Common Security Event (CSE)
// ASIM schema:   Network Session
// Deploy alias:  vimNetworkSessionOpenSystemsNdr
// Owner:         ndr team
// Aggregated by: ../../../../shared/parsers/vimNetworkSessionOpenSystems.kql
//
// NDR emits a Common Security Event (CSE) stream (distributor job ndr/ndr-eventprocessor),
// which this parser projects onto the ASIM Network Session schema
// (https://learn.microsoft.com/azure/sentinel/normalization-schema-network). Every CSE
// record carries the network 5-tuple (source/destination IP + port), protocol and
// direction of the connection that triggered the detection, so it also describes a
// network session; the detection context is carried in the optional inspection fields
// (Threat*). This mirrors the legacy NetworkSession NDR parser
// documented in docs/deprecated/vimNetworkSessionOpenSystemsNDR.md.
//
// Ingestion model (ADR-0002, native OTLP): logs land in the single OTelLogs table; the
// raw CSE JSON is the Body column, ingested as a string (parse with todynamic(Body)
// before dotted access); the discriminator is
// ResourceAttributes['osag.product.name'] == "ndr".
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    | where tostring(ResourceAttributes['osag.product.name']) == "ndr"
    | where tostring(ResourceAttributes['osag.stream']) != "alerts"
    // Body is ingested as a JSON string; parse it before dotted field access.
    | extend Body = todynamic(Body)
    | project
        TimeGenerated = todatetime(Body.date_time),
        EventStartTime = todatetime(Body.date_time),
        EventEndTime = todatetime(Body.date_time),
        EventCount = int(1),
        EventType = "NetworkSession",
        EventResult = "Success",
        EventOriginalType = tostring(Body.type),
        EventUid = tostring(Body.id),
        EventVendor = "Open Systems",
        EventProduct = "NDR",
        EventSchema = "NetworkSession",
        EventSchemaVersion = "0.2.7",
        EventSeverity = case(
            tostring(Body.severity) == "high", "High",
            tostring(Body.severity) == "medium", "Medium",
            tostring(Body.severity) == "low", "Low",
            "Informational"),
        EventOriginalSeverity = tostring(Body.severity),
        Dvc = tostring(Body.host_name),
        DvcHostname = tostring(Body.host_name),
        SrcIpAddr = tostring(Body.source.ip),
        SrcPortNumber = toint(Body.source.port),
        SrcHostname = tostring(Body.source.dns_name),
        SrcGeoCountry = tostring(Body.source.geoip.country_name),
        SrcGeoLatitude = todouble(Body.source.geoip.latitude),
        SrcGeoLongitude = todouble(Body.source.geoip.longitude),
        DstIpAddr = tostring(Body.destination.ip),
        DstPortNumber = toint(Body.destination.port),
        DstHostname = tostring(Body.destination.dns_name),
        DstGeoCountry = tostring(Body.destination.geoip.country_name),
        DstGeoLatitude = todouble(Body.destination.geoip.latitude),
        DstGeoLongitude = todouble(Body.destination.geoip.longitude),
        // Normalise protocol names to IANA standard: the NDR source emits "ICMPv4"
        // which is not an IANA name; the correct IANA name is "ICMP".
        NetworkProtocol = case(
            toupper(tostring(Body.ip_protocol_name)) == "ICMPV4", "ICMP",
            toupper(tostring(Body.ip_protocol_name)) == "ICMPV6", "IPV6-ICMP",
            tostring(Body.ip_protocol_name)),
        NetworkDirection = case(
            tostring(Body.traffic_direction) == "inbound", "Inbound",
            tostring(Body.traffic_direction) == "outbound", "Outbound",
            tostring(Body.traffic_direction) == "intra", "Local",
            ""),
        // Inspection context: the detection that observed this session.
        ThreatIpAddr = tostring(Body.correlation_ip),
        ThreatName = tostring(Body.ids.signature.signature_name),
        ThreatCategory = tostring(Body.ids.signature.classification_name),
        ThreatId = tostring(Body.ids.signature.classification_id),
        ThreatRiskLevel = toint(todouble(Body.threatscore) * 10),
        ThreatOriginalRiskLevel = tostring(Body.threatscore),
        AdditionalFields = bag_pack(
            "host_id", tostring(toint(todouble(Body.host_id))))
    // ASIM mandatory aliases and conditional fields required by ASimSchemaTester.
    | extend
        Type = EventType,
        IpAddr = SrcIpAddr,
        Hostname = DstHostname,
        // ThreatField is mandatory when ThreatIpAddr is present.
        ThreatField = case(
            ThreatIpAddr == SrcIpAddr, "SrcIpAddr",
            ThreatIpAddr == DstIpAddr, "DstIpAddr",
            "")
};
parser(starttime, endtime, disabled)

// Source:        NDR / Zeek conn.log
// ASIM schema:   Network Session
// Deploy alias:  vimNetworkSessionOpenSystemsZeek
// Owner:         ndr team
// Aggregated by: ../../../../shared/parsers/vimNetworkSessionOpenSystems.kql
//
// Per-source ("source-specific") ASIM parser. It is a member of the unifying
// Open Systems Network Session parser. Keep the filtering parameter signature so the
// unifying parser can push filters down for performance.
//
// Ingestion model (ADR-0002, native OTLP): all logs land in the single OTelLogs
// table. The raw Zeek record is the Body column, ingested as a string (parse with
// todynamic(Body) before field access); the product discriminator is the
// resource attribute osag.product.name. (Some legacy pipeline config still emits this as
// osag.log_type; the standard name is osag.product.name per ADR-0002.)
let parser = (
    starttime: datetime = datetime(null),
    endtime: datetime = datetime(null),
    disabled: bool = false
) {
    OTelLogs
    | where not(disabled)
    | where (isnull(starttime) or TimeGenerated >= starttime)
    | where (isnull(endtime) or TimeGenerated <= endtime)
    // 1. Discriminate on the resource attribute set by the OTel distributor.
    | where tostring(ResourceAttributes['osag.product.name']) == "zeek"
    // 1a. Cheap stream prefilter on raw JSON string to reduce rows before todynamic().
    | where Body has '"log":"conn.log"' or Body has '"log": "conn.log"'
    // Body is ingested as a JSON string; parse it before field access.
    | extend Body = todynamic(Body)
    // 1b. Zeek emits several streams (conn, dns, http, ssl ...) under one product,
    //     each mapping to a different ASIM schema. Select this stream by its Zeek log
    //     name, carried in Body.log (e.g. "conn.log").
    | where tostring(Body.log) == "conn.log"
    // 2. Map raw Body fields onto the ASIM Network Session schema (see schema.json).
    //    Zeek connection-tuple keys carry a literal dot (id.orig_h, id.resp_p), so they
    //    must be indexed with bracket notation, not dotted access. Body.ts is epoch
    //    seconds and Body.duration is in seconds (ASIM NetworkDuration is milliseconds).
    | project
        TimeGenerated = unixtime_seconds_todatetime(todouble(Body.ts)),
        EventStartTime = unixtime_seconds_todatetime(todouble(Body.ts)),
        EventEndTime = unixtime_seconds_todatetime(todouble(Body.ts) + todouble(Body.duration)),
        EventCount = int(1),
        EventType = "NetworkSession",
        EventResult = "Success",
        EventVendor = "Open Systems",
        EventProduct = "Zeek",
        EventSchema = "NetworkSession",
        EventSchemaVersion = "0.2.7",
        Dvc = "Zeek",
        DvcHostname = tostring(Body.host),
        NetworkSessionId = tostring(Body.uid),
        SrcIpAddr = tostring(Body["id.orig_h"]),
        SrcPortNumber = toint(Body["id.orig_p"]),
        DstIpAddr = tostring(Body["id.resp_h"]),
        DstPortNumber = toint(Body["id.resp_p"]),
        NetworkProtocol = toupper(tostring(Body.proto)),
        NetworkApplicationProtocol = tostring(Body.service),
        NetworkDirection = case(
            tobool(Body.local_orig) and tobool(Body.local_resp), "Local",
            tobool(Body.local_orig) and not(tobool(Body.local_resp)), "Outbound",
            not(tobool(Body.local_orig)) and tobool(Body.local_resp), "Inbound",
            "External"),
        SrcBytes = tolong(Body.orig_bytes),
        DstBytes = tolong(Body.resp_bytes),
        SrcPackets = tolong(Body.orig_pkts),
        DstPackets = tolong(Body.resp_pkts),
        NetworkDuration = toint(todouble(Body.duration) * 1000)
    // ASIM mandatory aliases required by ASimSchemaTester.
    | extend
        Type = EventType,
        IpAddr = SrcIpAddr,
        SessionId = NetworkSessionId,
        Duration = NetworkDuration
};
parser(starttime, endtime, disabled)

